SAMPLES   = 32
RES_SCALE = 100
POINT_PX  = 2.4              # grain size on screen
BRIGHT    = 1.0
KAPPA     = 0.015            # iso-density level of the surface (lower = rounder, higher = more lobes)
LINES     = 4                # white wavefronts per full turn of the phase
WAVE_SPEED = 0.5             # how fast the wavefronts travel (cycles per second)
SHIMMER   = 0.05             # living shimmer of the grains (0 = still)
#            cut away the top half (time open from, fully open, start closing, closed)
CUT = [(0.0, 0.0, 2.43, 2.44), (12.6, 13.6, 23.4, 24.4)]
HOLE_R    = 0.72             # radius of the hole (fraction of the shape size)
OUTPUT    = os.path.join(os.path.expanduser("~"), "OrbitalRenders", "one_electron")
NF = SECONDS * FPS
LENS = 40.0; KH = 18.0 / LENS; PXK = KH / 960.0
R_VIS = 10.0
#          n  l  m1  m2      each shape = (|n,l,m1> + |n,l,m2>) / sqrt2 : same energy, so the shape never changes
STATES = [(5, 4, 4, -2), (3, 2, 2, -1), (4, 3, 2, -1), (5, 4, 2, -3)]
#          state, hold from, hold to   (2.43 -> 2.44 is the hard cut back to the start)
HOLDS = [(0, 0.0, 2.43), (1, 2.44, 6.4), (2, 7.6, 11.8), (3, 13.0, 17.6), (0, 18.8, 30.0)]
T_EGG = (19.6, 20.0)         # easter egg: Schrodinger's cat

def ease(u):
    u = np.clip(u, 0, 1); return u * u * (3 - 2 * u)
T = np.arange(NF) / FPS
def fade(pairs): return np.interp(T, [p[0] for p in pairs], [p[1] for p in pairs])
def show(a, b, fi=0.4, fo=0.35): return [(0, 0), (max(a, 0.001), 0), (a + fi, 1), (b, 1), (b + fo, 0), (SECONDS, 0)]

#        time   dist  elev
KEYS = [(0.0, 44, 42), (2.43, 41, 40),
        (2.44, 54, 26), (6.4, 46, 22), (9.5, 42, 30), (12.4, 46, 30), (15.0, 42, 46), (17.6, 45, 40),
        (20.5, 41, 48), (23.0, 44, 30), (26.0, 39, 22), (30.0, 42, 22)]
def _cr(ts, vs, t):
    i = max(0, min(len(ts) - 2, int(np.searchsorted(ts, t, side="right")) - 1))
    p0, p1, p2, p3 = vs[max(i - 1, 0)], vs[i], vs[i + 1], vs[min(i + 2, len(vs) - 1)]
    u = (t - ts[i]) / (ts[i + 1] - ts[i])
    return 0.5 * (2 * p1 + (-p0 + p2) * u + (2 * p0 - 5 * p1 + 4 * p2 - p3) * u * u + (-p0 + 3 * p1 - 3 * p2 + p3) * u ** 3)
def keys_at(t):
    seg = KEYS[:2] if t < 2.435 else KEYS[2:]
    ts = [k[0] for k in seg]; t = min(max(t, ts[0]), ts[-1])
    d = _cr(ts, [k[1] for k in seg], t); e = _cr(ts, [k[2] for k in seg], t)
    az = (35 + 4 * t) if t < 2.435 else (-20 + 6.0 * (t - 2.44))
    return d, az, e

# ---------------- hydrogen superposition physics (atomic units) ----------------
def _fact(k): return float(math.factorial(k))

def legendre(l, m, x):
    s = np.sqrt(np.clip(1 - x * x, 0, None))
    pmm = np.ones_like(x)
    for i in range(1, m + 1): pmm = pmm * (-(2 * i - 1)) * s
    if l == m: return pmm
    pm1 = x * (2 * m + 1) * pmm
    if l == m + 1: return pm1
    for ll in range(m + 2, l + 1):
        pmm, pm1 = pm1, (x * (2 * ll - 1) * pm1 - (ll + m - 1) * pmm) / (ll - m)
    return pm1

def Ylm(l, m, th, ph):
    am = abs(m)
    y = math.sqrt((2 * l + 1) / (4 * math.pi) * _fact(l - am) / _fact(l + am)) * legendre(l, am, np.cos(th)) * np.exp(1j * am * ph)
    return y if m >= 0 else (-1) ** am * np.conj(y)

def ang(st, th, ph):
    """angular part of (|n,l,m1> + |n,l,m2>)/sqrt2 and its m-weighted sum"""
    n, l, m1, m2 = st
    y1, y2 = Ylm(l, m1, th, ph), Ylm(l, m2, th, ph)
    return (y1 + y2) / math.sqrt(2), (m1 * y1 + m2 * y2) / math.sqrt(2)

def radial2(n, l, r):
    return (2 * r / n) ** (2 * l) * np.exp(-2 * r / n)          # l = n-1 states: no radial nodes

def surface(st, N, rng, kappa):
    """grains on the iso-density surface rho = kappa * max(rho); returns x,y,z (scaled), colour, phase"""
    n, l, m1, m2 = st
    tg = np.linspace(1e-3, math.pi - 1e-3, 400); pg = np.linspace(0, 2 * math.pi, 800)
    TG, PG = np.meshgrid(tg, pg); amax = (np.abs(ang(st, TG, PG)[0]) ** 2).max()
    rr = np.linspace(1e-3, 12 * n * n, 20000); g = radial2(n, l, rr); ip = int(g.argmax())
    ro, go = rr[ip:], g[ip:] / g.max()                          # outer, decreasing branch
    X, Y, Z, C, CH, KEY, SP = [], [], [], [], [], [], []; got = 0
    rcap = None
    while got < N:
        M = 3_000_000
        th = np.arccos(rng.uniform(-1, 1, M)); ph = rng.uniform(0, 2 * math.pi, M)
        A, Am = ang(st, th, ph); a2 = np.abs(A) ** 2 / amax
        ok = a2 > kappa * 1.0001
        th, ph, A, Am, a2 = th[ok], ph[ok], A[ok], Am[ok], a2[ok]
        r = np.interp(kappa / a2, go[::-1], ro[::-1])            # outer crossing of R^2 |A|^2 = kappa
        if rcap is None: rcap = np.percentile(r, 99.5)
        keep = rng.random(len(r)) < (r / rcap) ** 2               # uniform grains per surface area
        th, ph, A, Am, r = th[keep], ph[keep], A[keep], Am[keep], r[keep]
        # soft shell: mostly just inside the surface, a few grains outside (fuzzy edge)
        dr = np.where(rng.random(len(r)) < 0.85, -np.abs(rng.normal(0, 0.035 * n * n, len(r))), np.abs(rng.normal(0, 0.012 * n * n, len(r))))
        r = r + dr
        # probability current on the sphere: v = grad(phase)
        vph = np.real(np.conj(A) * Am) / (np.abs(A) ** 2 + 1e-30) / (r * np.sin(th) + 1e-6)
        h = 1e-4; Ah = ang(st, th + h, ph)[0]
        vth = np.imag(np.conj(A) * (Ah - A) / h) / (np.abs(A) ** 2 + 1e-30) / r
        sp = np.sqrt(vph ** 2 + vth ** 2)
        X.append(r * np.sin(th) * np.cos(ph)); Y.append(r * np.sin(th) * np.sin(ph)); Z.append(r * np.cos(th))
        C.append(np.sign(vph) * sp); CH.append(np.angle(A) % (2 * math.pi)); SP.append(sp); KEY.append(np.round(th * 60) * 10 + ph)
        got += len(r)
    x, y, z, v, chi, key, spd = [np.concatenate(a)[:N] for a in (X, Y, Z, C, CH, KEY, SP)]
    med = np.median(np.abs(v)) + 1e-12
    f = np.clip(np.abs(v) / (np.abs(v) + 1.6 * med), 0, 1) ** 0.9
    c = np.where(v >= 0, 0.45 * (1 - f), 0.55 + 0.45 * f)
    lw = (spd > 0.35 * med).astype(np.float32)                   # wavefront lines only where the current flows
    sc = R_VIS / rcap
    o = np.argsort(key, kind="stable")                            # pair grains by direction for smooth morphs
    return (x * sc)[o], (y * sc)[o], (z * sc)[o], c[o], chi[o], lw[o], sc, med

def disk(st, N, rng, kappa, sc, med):
    """cross-section of the solid region rho > iso in the plane z = 0 (seen when the top half is cut away)"""
    n, l, m1, m2 = st
    pg = np.linspace(0, 2 * math.pi, 4000); amax = (np.abs(ang(st, np.linspace(1e-3, math.pi - 1e-3, 400)[:, None], pg[None, :])[0]) ** 2).max()
    rr = np.linspace(1e-3, 12 * n * n, 20000); g = radial2(n, l, rr); ip = int(g.argmax()); gm = g.max()
    ro, go = rr[ip:], g[ip:] / gm; ri, gi = rr[:ip + 1], g[:ip + 1] / gm
    th0 = math.pi / 2
    X, Y, C, CH, LW, KEY = [], [], [], [], [], []; got = 0
    while got < N:
        M = 2_000_000; ph = rng.uniform(0, 2 * math.pi, M)
        A0 = ang(st, np.full(M, th0), ph)[0]; a2 = np.abs(A0) ** 2 / amax
        ok = a2 > kappa * 1.0001; ph, a2 = ph[ok], a2[ok]
        r_out = np.interp(kappa / a2, go[::-1], ro[::-1]); r_in = np.interp(kappa / a2, gi, ri)
        area = r_out ** 2 - r_in ** 2
        keep = rng.random(len(ph)) < area / (np.percentile(area, 99.5) + 1e-9)
        ph, r_out, r_in = ph[keep], r_out[keep], r_in[keep]
        r = np.sqrt(rng.random(len(ph)) * (r_out ** 2 - r_in ** 2) + r_in ** 2)
        th = np.full(len(ph), th0); A, Am = ang(st, th, ph)
        vph = np.real(np.conj(A) * Am) / (np.abs(A) ** 2 + 1e-30) / r
        h = 1e-4; Ah = ang(st, th + h, ph)[0]
        vth = np.imag(np.conj(A) * (Ah - A) / h) / (np.abs(A) ** 2 + 1e-30) / r
        sp = np.sqrt(vph ** 2 + vth ** 2)
        X.append(r * np.cos(ph)); Y.append(r * np.sin(ph)); C.append(np.sign(vph) * sp); CH.append(np.angle(A) % (2 * math.pi))
        LW.append((sp > 0.35 * med).astype(np.float32)); KEY.append(np.round(ph * 300) * 1000 + r)
        got += len(ph)
    x, y, v, chi, lw, key = [np.concatenate(a)[:N] for a in (X, Y, C, CH, LW, KEY)]
    f = np.clip(np.abs(v) / (np.abs(v) + 1.6 * med), 0, 1) ** 0.9
    c = np.where(v >= 0, 0.45 * (1 - f), 0.55 + 0.45 * f)
    z = -np.abs(rng.normal(0, 0.006 * n * n, N))
    o = np.argsort(key, kind="stable")
    return (x * sc)[o], (y * sc)[o], (z * sc)[o], c[o], chi[o], lw[o]

def make_state(st, N, rng, kappa, disk_frac=0.14):
    Nd = int(N * disk_frac); Ns = N - Nd
    xs, ys, zs, cs, chs, lws, sc, med = surface(st, Ns, rng, kappa)
    xd, yd, zd, cd, chd, lwd = disk(st, Nd, rng, kappa, sc, med)
    return [np.concatenate(a) for a in ((xs, xd), (ys, yd), (zs, zd), (cs, cd), (chs, chd), (lws, lwd))]

def weights():
    W = np.zeros((NF, len(STATES)))
    for i, (k, a, b) in enumerate(HOLDS):
        W[(T >= a) & (T <= b), k] = 1.0
        if i + 1 < len(HOLDS):
            k2, a2, _ = HOLDS[i + 1]
            if a2 - b > 0.05:
                sel = (T > b) & (T < a2); u = ease((T[sel] - b) / (a2 - b))
                W[sel, k] += 1 - u; W[sel, k2] += u
            else:
                W[(T > b) & (T < a2), k2] = 1.0
    return W

def surface_group(name, Ws, Dt, Dr, mat):
    ng, N_, Lk, gi, go = new_gn(name)
    w = [c for W_ in Ws for c in drv(N_, Lk, W_)]
    dt = drv(N_, Lk, Dt); dr = drv(N_, Lk, Dr)
    def at(nm):
        n_ = N_.new("GeometryNodeInputNamedAttribute"); n_.data_type = 'FLOAT'; n_.inputs["Name"].default_value = nm; return n_.outputs["Attribute"]
    pos = rs = cs = ls = None
    for k in range(len(STATES)):
        x, y, z, c, chi, lw = (at(f"{a}{k}") for a in ("x", "y", "z", "c", "chi", "lw"))
        v = N_.new("ShaderNodeCombineXYZ"); Lk.new(x, v.inputs[0]); Lk.new(y, v.inputs[1]); Lk.new(z, v.inputs[2])
        sv = N_.new("ShaderNodeVectorMath"); sv.operation = 'SCALE'; Lk.new(v.outputs[0], sv.inputs[0]); Lk.new(w[k], sv.inputs["Scale"])
        ln = N_.new("ShaderNodeVectorMath"); ln.operation = 'LENGTH'; Lk.new(v.outputs[0], ln.inputs[0])
        r = M_(N_, Lk, 'MULTIPLY', w[k], ln.outputs["Value"])
        # travelling wavefronts: thin bands of constant (phase - wave clock)
        u = M_(N_, Lk, 'SUBTRACT', M_(N_, Lk, 'MULTIPLY', chi, LINES / (2 * math.pi)), dt[0])
        fr = M_(N_, Lk, 'FRACT', u)
        d = M_(N_, Lk, 'MINIMUM', fr, M_(N_, Lk, 'SUBTRACT', 1.0, fr))
        band = M_(N_, Lk, 'MAXIMUM', 0.0, M_(N_, Lk, 'SUBTRACT', 1.0, M_(N_, Lk, 'MULTIPLY', d, 22.0)))
        lk_ = M_(N_, Lk, 'MULTIPLY', w[k], M_(N_, Lk, 'MULTIPLY', band, lw))
        cw = M_(N_, Lk, 'MULTIPLY', w[k], c)
        if pos is None: pos, rs, cs, ls = sv.outputs[0], r, cw, lk_
        else:
            ad = N_.new("ShaderNodeVectorMath"); ad.operation = 'ADD'; Lk.new(pos, ad.inputs[0]); Lk.new(sv.outputs[0], ad.inputs[1]); pos = ad.outputs[0]
            rs = M_(N_, Lk, 'ADD', rs, r); cs = M_(N_, Lk, 'ADD', cs, cw); ls = M_(N_, Lk, 'ADD', ls, lk_)
    # keep the radius while morphing (grains glide over the surface instead of collapsing inward)
    ad = N_.new("ShaderNodeVectorMath"); ad.operation = 'ADD'; Lk.new(pos, ad.inputs[0]); ad.inputs[1].default_value = (1e-4, 1e-4, 1e-4)
    nv = N_.new("ShaderNodeVectorMath"); nv.operation = 'NORMALIZE'; Lk.new(ad.outputs[0], nv.inputs[0])
    shim = M_(N_, Lk, 'MULTIPLY', SHIMMER, M_(N_, Lk, 'SINE', M_(N_, Lk, 'ADD', M_(N_, Lk, 'MULTIPLY', at("rnd"), 60.0), M_(N_, Lk, 'MULTIPLY', dt[1], 7.0))))
    sc = N_.new("ShaderNodeVectorMath"); sc.operation = 'SCALE'; Lk.new(nv.outputs[0], sc.inputs[0]); Lk.new(M_(N_, Lk, 'ADD', rs, shim), sc.inputs["Scale"])
    setp = N_.new("GeometryNodeSetPosition"); Lk.new(gi.outputs[0], setp.inputs["Geometry"]); Lk.new(sc.outputs[0], setp.inputs["Position"])
    st = N_.new("GeometryNodeStoreNamedAttribute"); st.data_type = 'FLOAT'; st.domain = 'POINT'; st.inputs["Name"].default_value = "col"
    Lk.new(setp.outputs[0], st.inputs["Geometry"]); Lk.new(cs, st.inputs["Value"])
    st2 = N_.new("GeometryNodeStoreNamedAttribute"); st2.data_type = 'FLOAT'; st2.domain = 'POINT'; st2.inputs["Name"].default_value = "wht"
    Lk.new(st.outputs[0], st2.inputs["Geometry"]); Lk.new(ls, st2.inputs["Value"])
    spz = N_.new("ShaderNodeSeparateXYZ"); Lk.new(sc.outputs[0], spz.inputs[0])
    sxy = M_(N_, Lk, 'SQRT', M_(N_, Lk, 'ADD', M_(N_, Lk, 'MULTIPLY', spz.outputs[0], spz.outputs[0]), M_(N_, Lk, 'MULTIPLY', spz.outputs[1], spz.outputs[1])))
    hole = M_(N_, Lk, 'MULTIPLY', M_(N_, Lk, 'GREATER_THAN', spz.outputs[2], dt[2]), M_(N_, Lk, 'LESS_THAN', sxy, HOLE_R * R_VIS))
    kept = M_(N_, Lk, 'SUBTRACT', 1.0, hole)                                # cut: a round hole from the top down to the middle
    rad = M_(N_, Lk, 'MULTIPLY', M_(N_, Lk, 'MULTIPLY', dr[0], kept), M_(N_, Lk, 'ADD', 0.75, M_(N_, Lk, 'MULTIPLY', at("rnd"), 0.5)))
    mp = N_.new("GeometryNodeMeshToPoints"); Lk.new(st2.outputs[0], mp.inputs["Mesh"]); Lk.new(rad, mp.inputs["Radius"])
    sm = N_.new("GeometryNodeSetMaterial"); sm.inputs["Material"].default_value = mat
    Lk.new(mp.outputs[0], sm.inputs["Geometry"]); Lk.new(sm.outputs[0], go.inputs[0])
    return ng

def grain_mat(name):
    m = bpy.data.materials.new(name); m.use_nodes = True
    N_, Lk = m.node_tree.nodes, m.node_tree.links; N_.clear()
    out = N_.new("ShaderNodeOutputMaterial"); p = N_.new("ShaderNodeBsdfPrincipled")
    at = N_.new("ShaderNodeAttribute"); at.attribute_type = 'GEOMETRY'; at.attribute_name = "col"
    aw = N_.new("ShaderNodeAttribute"); aw.attribute_type = 'GEOMETRY'; aw.attribute_name = "wht"
    cr = N_.new("ShaderNodeValToRGB"); el = cr.color_ramp.elements
    # counterclockwise: crimson (fast) .. orange (slow) | clockwise: green (slow) .. blue (fast)
    el[0].position = 0.0; el[0].color = (0.85, 0.0, 0.07, 1); el[1].position = 1.0; el[1].color = (0.02, 0.06, 1.0, 1)
    for pos_, c in ((0.25, (1.0, 0.1, 0.04)), (0.45, (1.0, 0.42, 0.0)), (0.5, (1.0, 0.9, 0.7)), (0.55, (0.0, 0.75, 0.32)), (0.78, (0.0, 0.48, 0.75))):
        e = el.new(pos_); e.color = (*c, 1)
    Lk.new(at.outputs["Fac"], cr.inputs[0])
    mx = N_.new("ShaderNodeMix"); mx.data_type = 'RGBA'
    try:
        Lk.new(M_(N_, Lk, 'MINIMUM', aw.outputs["Fac"], 1.0), mx.inputs["Factor"]); Lk.new(cr.outputs[0], mx.inputs[6]); mx.inputs[7].default_value = (1, 1, 1, 1)
        col = mx.outputs[2]
    except Exception: col = cr.outputs[0]
    Lk.new(col, p.inputs["Base Color"])
    p.inputs["Metallic"].default_value = 0.05; p.inputs["Roughness"].default_value = 0.38
    try: p.inputs["Coat Weight"].default_value = 0.2; p.inputs["Coat Roughness"].default_value = 0.15
    except Exception: pass
    try:
        Lk.new(col, p.inputs["Emission Color"])
        Lk.new(M_(N_, Lk, 'MULTIPLY', M_(N_, Lk, 'ADD', 0.07, M_(N_, Lk, 'MULTIPLY', aw.outputs["Fac"], 1.1)), BRIGHT), p.inputs["Emission Strength"])
    except Exception: pass
    Lk.new(p.outputs[0], out.inputs[0])
    return m

def build_lights():
    import mathutils
    def light(name, loc, energy, rgb, ang_=3):
        ld = bpy.data.lights.new(name, 'SUN'); ld.energy = energy * BRIGHT; ld.color = rgb
        try: ld.use_shadow = True; ld.angle = math.radians(ang_)
        except Exception: pass
        o = link(bpy.data.objects.new(name, ld)); o.location = loc
        o.rotation_euler = (mathutils.Vector((0, 0, 0)) - mathutils.Vector(loc)).to_track_quat('-Z', 'Y').to_euler()
    light("Key", (-40, 50, 80), 5.6, (1.0, 0.96, 0.9))
    light("Rim", (60, -60, 30), 1.6, (0.85, 0.9, 1.0))
    light("Fill", (70, 40, -20), 0.8, (1.0, 0.92, 0.85), 10)

# ---------------- build ----------------
def build():
    import mathutils
    scene = bpy.context.scene
    clear_scene()
    rng = np.random.default_rng(1926)
    print(f"[1/4] {len(STATES)} electron shapes x {N_TOTAL:,} grains (about 1 minute)...")
    W = weights()
    me = bpy.data.meshes.new("Electron"); me.vertices.add(N_TOTAL)
    me.vertices.foreach_set("co", np.zeros(3 * N_TOTAL, np.float32))
    for k, st in enumerate(STATES):
        arrs = make_state(st, N_TOTAL, rng, KAPPA)
        for key, arr in zip(("x", "y", "z", "c", "chi", "lw"), arrs):
            a = me.attributes.new(f"{key}{k}", 'FLOAT', 'POINT'); a.data.foreach_set("value", arr.astype(np.float32))
        del arrs; print(f"      shape {k + 1}/{len(STATES)} done")
    a = me.attributes.new("rnd", 'FLOAT', 'POINT'); a.data.foreach_set("value", rng.random(N_TOTAL).astype(np.float32))
    me.update()

    print("[2/4] Camera...")
    C = np.zeros((NF, 3)); EUL = np.zeros((NF, 3)); RM = np.zeros((NF, 3, 3)); DIST = np.zeros(NF)
    for f in range(NF):
        dist, az, el = keys_at(T[f]); a_ = math.radians(az); e = math.radians(el)
        cam = dist * np.array([math.cos(e) * math.cos(a_), math.cos(e) * math.sin(a_), math.sin(e)])
        fwd = -cam / np.linalg.norm(cam); right = np.cross(fwd, [0, 0, 1]); right /= np.linalg.norm(right); up = np.cross(right, fwd)
        cam = cam - up * 0.10 * dist           # pan: the shape sits above the captions
        R_ = np.stack([right, up, -fwd], 1); C[f] = cam; RM[f] = R_; DIST[f] = dist
        EUL[f] = mathutils.Matrix(R_.tolist()).to_euler('XYZ')
    EUL = np.unwrap(EUL, axis=0)
    cd = bpy.data.cameras.new("Camera"); cd.lens = LENS; cd.sensor_fit = 'VERTICAL'; cd.sensor_height = 36
    cd.clip_start = 0.1; cd.clip_end = 1000
    camo = link(bpy.data.objects.new("Camera", cd)); scene.camera = camo
    for j in range(3): bake(camo, "location", j, C[:, j]); bake(camo, "rotation_euler", j, EUL[:, j])

    print("[3/4] Surface + flow...")
    Ws = []
    for i in range(2):
        E_ = link(bpy.data.objects.new(f"Drive_w{i}", None)); E_.hide_render = True
        for j in range(3):
            k = 3 * i + j
            bake(E_, "location", j, W[:, k] if k < len(STATES) else np.zeros(NF))
        Ws.append(E_)
    Dt = link(bpy.data.objects.new("Drive_wave", None)); Dt.hide_render = True
    bake(Dt, "location", 0, WAVE_SPEED * T); bake(Dt, "location", 1, T)
    H = np.full(NF, 99.0)
    for a_, b_, c_, d_ in CUT:
        sel = (T >= a_) & (T <= d_)
        op = np.minimum(ease((T[sel] - a_) / max(b_ - a_, 1e-3)) if b_ > a_ else 1.0, 1 - ease((T[sel] - c_) / max(d_ - c_, 1e-3)))
        H[sel] = np.minimum(H[sel], 0.02 + (1 - op) * 1.3 * R_VIS)
    bake(Dt, "location", 2, H)
    Dr = link(bpy.data.objects.new("Drive_radius", None)); Dr.hide_render = True
    bake(Dr, "location", 0, POINT_PX * PXK * DIST / 2)
    ob = link(bpy.data.objects.new("Electron", me)); ob.modifiers.new("psi", 'NODES').node_group = surface_group("ElectronSurface", Ws, Dt, Dr, grain_mat("Grains"))

    print("[4/4] Text...")
    imgs, font = load_assets()
    def hud(ob_, cx, cy, depth=0.25):
        d = DIST * depth
        loc = np.array([C[f] + RM[f] @ np.array([(cx - 540) * PXK * d[f], (960 - cy) * PXK * d[f], -d[f]]) for f in range(NF)])
        for j in range(3): bake(ob_, "location", j, loc[:, j]); bake(ob_, "rotation_euler", j, EUL[:, j]); bake(ob_, "scale", j, PXK * d)
    def pic(name, cx, cy, alpha, anchor="c"):
        im = imgs[name]; w_, h_ = im.size
        if anchor == "tl": cx, cy = cx + w_ / 2, cy + h_ / 2
        if anchor == "bl": cx, cy = cx + w_ / 2, cy - h_ / 2
        me_ = bpy.data.meshes.new(name)
        me_.from_pydata([(-w_ / 2, -h_ / 2, 0), (w_ / 2, -h_ / 2, 0), (w_ / 2, h_ / 2, 0), (-w_ / 2, h_ / 2, 0)], [], [(0, 1, 2, 3)])
        uv_ = me_.uv_layers.new(); uv_.data.foreach_set("uv", [0, 0, 1, 0, 1, 1, 0, 1])
        o_ = link(bpy.data.objects.new(name, me_)); m_, v_ = image_mat(name, im); me_.materials.append(m_)
        hud(o_, cx, cy); bake(v_.outputs[0], "default_value", None, alpha if isinstance(alpha, np.ndarray) else fade(alpha), owner=m_.node_tree)
    pic("title", 540, 150, np.ones(NF))
    pic("t_hook", 540, 1420, [(0, 1), (2.25, 1), (2.42, 0), (SECONDS, 0)])
    for nm, a, b in (("t1", 2.6, 6.5), ("t2", 7.5, 11.9), ("t3", 12.9, 16.9), ("t4", 17.9, 20.6), ("t5", 20.9, 23.4), ("t6", 23.9, 26.8)):
        pic(nm, 540, 1420, show(a, b))
    pic("t_end", 540, 1420, [(0, 0), (27.1, 0), (27.7, 1), (SECONDS, 1)])
    for k in range(len(STATES)):
        al = ease((W[:, k] - 0.35) / 0.3)
        pic(f"lab{k}", 60, 1632, al, "tl")
    pic("legend", 60, 1612, np.ones(NF), "bl")
    pic("handle", 540, 1880, np.ones(NF))
    pic("cat", 880, 1180, [(0, 0), (T_EGG[0], 0), (T_EGG[0] + 0.08, 0.9), (T_EGG[1] - 0.08, 0.9), (T_EGG[1], 0), (SECONDS, 0)])

    build_world(); build_lights(); setup_render(scene); add_bloom(scene)
    r_ = scene.render; r_.fps = FPS
    for k_, v_ in (('use_gtao', True), ('gtao_distance', 1.2), ('use_raytracing', True), ('fast_gi_method', 'GLOBAL_ILLUMINATION'),
                   ('use_shadows', True), ('shadow_ray_count', 2), ('shadow_step_count', 8)):
        try: setattr(scene.eevee, k_, v_)
        except Exception: pass
    try: r_.use_motion_blur = False
    except Exception: pass
    try: scene.view_settings.view_transform = 'AgX'; scene.view_settings.look = 'AgX - Punchy'; scene.view_settings.exposure = 0.45
    except Exception: pass
    for scr in bpy.data.screens:
        for area in scr.areas:
            if area.type == 'VIEW_3D':
                for sp_ in area.spaces:
                    if sp_.type == 'VIEW_3D':
                        try: sp_.shading.use_compositor = 'DISABLED'
                        except Exception: pass
    scene.frame_end = NF; scene.frame_set(1)
    print(f"Ready: {NF} frames @ {FPS} fps, {N_TOTAL:,} grains. Ctrl+F12 -> {scene.render.filepath}")

def _deferred():
    try: build()
    except Exception:
        import traceback; traceback.print_exc()
    return None

if bpy.app.background:
    build()
else:
    print("Building... (Window > Toggle System Console to watch)")
    bpy.app.timers.register(_deferred, first_interval=0.2)
